"use client";
import React, { useState, useEffect } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import Sidebar from "../../components/sidebar";
import Navbar from "../../components/Navbar";
import { HiArrowNarrowLeft } from "react-icons/hi";

const AddSujet = () => {
  const [inputs, setInputs] = useState({
    titre: "",
    idEncadrant: "",
  });

  const [encadrants, setEncadrants] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [loading, setLoading] = useState(false); // Ajout d'un état de chargement
  const router = useRouter();

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/encadrants")
      .then((response) => {
        console.log("Encadrants:", response.data); // Debugging
        setEncadrants(response.data);
      })
      .catch((error) => {
        console.error("Erreur lors du chargement des encadrants:", error);
        setError("Erreur lors du chargement des encadrants.");
      });
  }, []);

  const handleChange = (event) => {
    const { name, value } = event.target;

    setInputs((prevValues) => ({
      ...prevValues,
      [name]: value,
    }));

    if (name === "idEncadrant") {
      const selectedEncadrant = encadrants.find((enc) => enc.idEncadrant === value);
      if (selectedEncadrant) {
        setInputs((prevValues) => ({
          ...prevValues,
          titre: `Sujet de ${selectedEncadrant.nom} ${selectedEncadrant.prenom}`,
        }));
      }
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError(null);
    setSuccess(null);
    setLoading(true); // Activer l'état de chargement

    try {
      const response = await axios.post("http://localhost:5000/api/addSujet", {
        titre: inputs.titre,
        idEncadrant: inputs.idEncadrant,
      });

      console.log("Réponse du serveur :", response.data);
      setSuccess("Sujet ajouté avec succès.");
      setTimeout(() => router.push("/users/readSuj"), 2000);
    } catch (err) {
      console.error("Erreur lors de l'ajout de sujet:", err);
      if (err.response) {
        setError(`Erreur du serveur: ${err.response.data.message}`);
      } else {
        setError("Erreur de connexion au serveur.");
      }
    } finally {
      setLoading(false); // Désactiver l'état de chargement
    }
  };

  const handleGoBack = () => {
    router.push("/users/readSuj");
  };

  return (
    <div className="flex h-screen w-screen bg-gray-50">
      {/* Sidebar */}
      <Sidebar className="h-screen" />

      <div className="w-full flex flex-col h-screen">
        {/* Navbar */}
        <Navbar />

        {/* Contenu principal */}
        <div className="w-full flex-1 py-5 flex flex-col items-center overflow-auto">
          <div className="bg-white shadow-2xl rounded-2xl p-8 w-full max-w-lg border border-gray-100 transform transition-transform duration-300 hover:scale-101">
            {/* Bouton de retour */}
            <button
              onClick={handleGoBack}
              className="mb-5 flex items-center text-blue-600 hover:text-blue-800 transition font-medium text-lg"
            >
              <HiArrowNarrowLeft className="mr-2 text-2xl" />
             
            </button>

            {/* Titre */}
            <h1 className="text-3xl font-bold text-center text-gray-800 mb-6">
              Ajouter un Sujet
            </h1>

            {/* Affichage des messages */}
            {error && <div className="text-red-500 mb-4">{error}</div>}
            {success && <div className="text-green-500 mb-4">{success}</div>}

            {/* Formulaire */}
            <form onSubmit={handleSubmit}>
              {/* Nom du sujet */}
              <div className="mb-4">
                <label htmlFor="titre" className="block text-sm font-medium text-gray-700 mb-1">
                  Nom du sujet
                </label>
                <input
                  type="text"
                  name="titre"
                  id="titre"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  placeholder="Nom du sujet..."
                  onChange={handleChange}
                  value={inputs.titre}
                  required
                />
              </div>

              {/* Sélectionner un encadrant */}
              <div className="mb-4">
                <label htmlFor="idEncadrant" className="block text-sm font-medium text-gray-700 mb-1">
                  Sélectionner un encadrant
                </label>
                <select
                  name="idEncadrant"
                  id="idEncadrant"
                  className="w-full px-4 py-2 mt-1 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all"
                  onChange={handleChange}
                  value={inputs.idEncadrant || ""}
                  required
                >
                  <option value="" disabled>
                    Choisir un encadrant
                  </option>
                  {encadrants.map((encadrant) => (
                    <option key={encadrant.idEncadrant} value={encadrant.idEncadrant}>
                      {encadrant.nom} {encadrant.prenom}
                    </option>
                  ))}
                </select>
              </div>

              {/* Bouton Ajouter */}
              <button
                type="submit"
               
                className="w-full bg-blue-600 text-white font-semibold py-2 px-4 rounded-lg hover:bg-blue-700 focus:ring-2 focus:ring-blue-500 transition-all disabled:bg-gray-400 disabled:cursor-not-allowed"
              >
                {loading ? "Chargement..." : "Ajouter"}
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AddSujet;